"""Publish only the actual passing refined M03 model's offline review page."""
from pathlib import Path
import hashlib,html,json
P=Path(__file__).resolve().parent;ROOT=P.parents[1];OUT=ROOT/'review/M03/Review01'

def main():
    qa=json.loads((OUT/'validation_summary.json').read_text());build=json.loads((OUT/'build_manifest.json').read_text());renders=json.loads((OUT/'render_manifest.json').read_text())
    assert qa['technical_pass'] and build['phase']=='refined' and len(renders['images'])==11
    cards=''.join(f'<article><a href="{r["file"]}"><img loading="lazy" src="{r["file"]}" alt="{html.escape(r["title"])}"></a><h3>{i:02d} / {html.escape(r["title"]).upper()}</h3></article>' for i,r in enumerate(renders['images'],1))
    dims=' × '.join(f'{d/100:.2f}' for d in qa['dimensions_cm'])
    body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lancer M03 · Production Review 01</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#0b1118;color:#dce8ef;font:16px/1.6 Segoe UI,Arial,sans-serif}}header,main,footer{{max-width:1500px;margin:auto;padding:28px 34px}}header{{border-bottom:1px solid #2c4554}}h1{{font-size:36px;letter-spacing:4px;margin:6px 0}}.tag{{color:#3bc8ff;font-size:12px;letter-spacing:3px}}a{{color:#77d9ff}}.hero{{width:100%;display:block;border-radius:12px}}.metrics{{display:flex;gap:16px;flex-wrap:wrap;margin:22px 0}}.metrics div{{flex:1;min-width:170px;background:#152633;border:1px solid #324b5c;border-radius:9px;padding:16px}}.metrics b{{display:block;color:#b4e7ff;font-size:22px}}.metrics span{{font-size:12px;color:#9eb6c5}}.notice{{border-left:3px solid #2cbcff;background:#112430;padding:18px 24px;margin:24px 0}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}}article{{border:1px solid #2e4858;border-radius:10px;overflow:hidden;background:#12232f}}article img{{width:100%;display:block}}article h3{{margin:14px 20px;font-size:13px;letter-spacing:1px}}.links{{display:flex;flex-wrap:wrap;gap:18px;margin:24px 0}}h2{{margin:30px 0 12px}}footer{{font-size:13px;color:#9eb6c5;border-top:1px solid #2c4554}}@media(max-width:750px){{.grid{{grid-template-columns:1fr}}header,main,footer{{padding:20px}}h1{{font-size:28px}}}}
</style></head><body><header><div class="tag">TRIAD DRIFT / SHIPS & WEAPONS / LANCER</div><h1>M03 / PRODUCTION REVIEW 01</h1><div>Approved blue reference · Military graphite redesign · Visual acceptance pending</div></header><main>
<a href="01_hero_front_3q.png"><img class="hero" src="01_hero_front_3q.png" alt="Actual Lancer M03 Blender model"></a>
<div class="metrics"><div><b>{qa['assembly_triangles']:,}</b><span>ASSEMBLED TRIANGLES</span></div><div><b>{dims} m</b><span>LENGTH × SPAN × HEIGHT</span></div><div><b>{qa['materials']} / 33</b><span>MATERIALS / PRESERVED LEGACY FRAMES</span></div><div><b>{qa['emissive_surface_fraction']*100:.2f}%</b><span>EMISSIVE TRIANGLE SURFACE</span></div></div>
<div class="notice"><p><strong>Technically verified source review — Nick's visual approval required.</strong></p><p>A new reference-led angular hull, low framed cockpit, independent wings and twin drives, layered graphite armor and two continuous forward cyan conduits replace the superseded visual direction. Every view below comes from the same actual Blender scene. No native import or gameplay validation is claimed.</p><p>The old33 frames remain unchanged. Single-bore cannons retain old barrel reference points; discreet underwing rocket bays preserve the eight functional exits omitted by the reference. Inspect their fit in the bottom view. Runtime bank/socket adoption remains an engineering gate.</p></div>
<h2>Primary design authority</h2><a href="../../../production/M03/refs/Lancer_M03_authority.png"><img class="hero" src="../../../production/M03/refs/Lancer_M03_authority.png" alt="Nick supplied blue Lancer turnaround"></a><p>Supplied concept, not an output render. Compare proportions across its views; minor inconsistencies in the concept are documented in the review report.</p>
<h2>Actual model — six orthographic directions and beauty</h2><p>Click for full resolution. Bright and dark studio views preserve geometry and emission settings; framing is independent across views.</p><div class="grid">{cards}</div>
<h2>Construction / topology</h2><a href="Lancer_M03_clay_sheet.png"><img class="hero" src="Lancer_M03_clay_sheet.png" alt="Six-angle clay review"></a><a href="Lancer_M03_wire_sheet.png"><img class="hero" src="Lancer_M03_wire_sheet.png" alt="Actual edge wire overlays"></a>
<p>See the independent art review and measured report for remaining limitations. Source microfinish uses Blender nodes and must be baked or reconstructed before Unreal adoption. This page does not declare final AAA approval.</p>
<div class="links"><a href="Lancer_M03_overview.png">One-image overview</a><a href="report.md">Technical and art review</a><a href="validation_summary.json">Measured validation</a><a href="../../../production/M03/Lancer_M03_v01.blend">Blender source</a><a href="../../../production/M03/README.md">Source / handoff notes</a><a href="../../../production/M03/legacy_mapping_proposal.json">Legacy mapping</a><a href="../../../production/M03/material_parameters.json">Material controls</a></div>
</main><footer>Ships & Weapons Agent · nick/ships-lancer-m03 · Nick approval before Bastion, then Rift · No native/main integration.</footer></body></html>'''
    (OUT/'index.html').write_text(body,encoding='utf-8')
    records=[dict(file=p.name,absolute_path=str(p.resolve()),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(OUT.glob('*.png'))]
    (OUT/'delivery_manifest.json').write_text(json.dumps(dict(images=records,source_absolute_path=str((P/'Lancer_M03_v01.blend').resolve()),review_absolute_path=str((OUT/'index.html').resolve()),technical_pass=True,visual_approval=False,native_imported=False),indent=2)+'\n')
    print(json.dumps(dict(review=str(OUT/'index.html'),images=len(records))))

if __name__=='__main__':main()
